<script>
  // Dynamically builds mega-menu hrefs using data-service-slug and data-anchor
  document.addEventListener('DOMContentLoaded', function () {
    const links = document.querySelectorAll('.mega-menu-link[data-service-slug]');

    if (links.length === 0) {
      console.warn('No elements found with class .mega-menu-link and data-service-slug attribute.');
      return;
    }

    links.forEach((link) => {
      if (link.dataset.serviceSlug && link.dataset.anchor) {
        link.href = `/services/${link.dataset.serviceSlug}#${link.dataset.anchor}`;
      }
    });
  });

  // Hide rollover-animation JS
  gsap.registerPlugin(ScrollTrigger);

  ScrollTrigger.create({
    trigger: 'footer',
    start: 'top 40%',
    onEnter: () => {
      gsap.to('.rollover-animation', {
        opacity: 0,
        pointerEvents: 'none',
        duration: 0.3,
      });
    },
    onLeaveBack: () => {
      gsap.to('.rollover-animation', {
        opacity: 1,
        pointerEvents: 'auto',
        duration: 0.3,
      });
    },
  });

  // Initialize Lenis
  const lenis = new Lenis({
    smooth: true,
    lerp: 0.1,
    wheelMultiplier: 1,
    infinite: false,
  });

  // Use requestAnimationFrame to continuously update the scroll
  function raf(time) {
    lenis.raf(time);
    requestAnimationFrame(raf);
  }

  requestAnimationFrame(raf);

  $(window).on('scroll', function () {
    if ($('.hero_banner').length) {
      // Hero banner exists
      const heroHeight = $('.hero_banner').outerHeight() - 100;

      if ($(window).scrollTop() > heroHeight) {
        $('body').addClass('header-sticky');
      } else {
        $('body').removeClass('header-sticky');
      }
    } else {
      // Default for pages without hero banner
      if ($(window).scrollTop() > 0) {
        $('body').addClass('header-sticky');
      } else {
        $('body').removeClass('header-sticky');
      }
    }
  });

  // footer JS Start
  function setInitialState() {
    if ($(window).width() < 767) {
      $('.footer-bottom-link-ul').hide();
      $('.footer-bottom-link-toggle').text('+');
      $('.footer-bottom-col-wrp').removeClass('is-open');
    } else {
      $('.footer-bottom-link-ul').css('display', '');
      $('.footer-bottom-col-wrp').removeClass('is-open');
    }
  }

  $('.footer-bottom-col-wrp').on('click', function (e) {
    e.preventDefault();

    if ($(window).width() < 767) {
      var $wrp = $(this);

      var $ul = $wrp.parent().find('.footer-bottom-link-ul').first();

      var $toggle = $wrp.find('.footer-bottom-link-toggle');
      var isOpen = $ul.is(':visible');

      $('.footer-bottom-link-ul').not($ul).slideUp(200);
      $('.footer-bottom-link-toggle').not($toggle).text('+');
      $('.footer-bottom-col-wrp').not($wrp).removeClass('is-open');

      if (isOpen) {
        $ul.slideUp(200);
        $toggle.text('+');
        $wrp.removeClass('is-open');
      } else {
        $ul.slideDown(200);
        $toggle.text('-');
        $wrp.addClass('is-open');
      }
    }
  });

  setInitialState();

  $(window).on('resize', function () {
    setInitialState();
  });
  // footer JS End

  // Menu JS Start
  $('.mobile-menu-toggle').on('click', function (e) {
    e.preventDefault();
    $('.navbar').addClass('menu-open');
  });

  $('.mobile-menu-close-btn').on('click', function (e) {
    e.preventDefault();
    $('.navbar').removeClass('menu-open');
  });

  function initDefaultSubmenu() {
    const $firstSubmenu = $('.navbar-li.has-submenu').first();
    if ($firstSubmenu.length) {
      $firstSubmenu.addClass('submenu-open');
      $firstSubmenu.find('> .nav-sub-menu-block').show();
      $firstSubmenu.find('> .navbar-link-wrp .sub-menu-toggle-btn').text('-');
    }
  }

  function handleSubmenuEvents() {
    if ($(window).width() >= 992) {
      $('.has-submenu').removeClass('submenu-open');
      $('.nav-sub-menu-block').removeAttr('style');
      $('.sub-menu-toggle-btn').text('+');
    }

    initDefaultSubmenu();
  }

  if ($(window).width() < 992) {

    $('.navbar-ul > .navbar-li:first-child .navbar-link-wrp').on('click', function (e) {
      e.preventDefault();
      const $parent = $(this).closest('.has-submenu');
      const $submenu = $parent.children('.nav-sub-menu-block');
      const $btn = $(this).find('.sub-menu-toggle-btn');
      const isOpening = !$parent.hasClass('submenu-open');
      closeOtherMenus($parent);
      $parent.toggleClass('submenu-open');
      $btn.text(isOpening ? '-' : '+');
      $submenu.stop(true, true).slideToggle(300);
    });

    $('.navbar-ul > .navbar-li:not(:first-child) .sub-menu-toggle-btn').on('click', function (e) {
      e.preventDefault();
      e.stopPropagation();

      const $btn = $(this);
      const $parent = $btn.closest('.has-submenu');
      const $submenu = $parent.children('.nav-sub-menu-block');
      const isOpening = !$parent.hasClass('submenu-open');
      closeOtherMenus($parent);
      $parent.toggleClass('submenu-open');
      $btn.text(isOpening ? '-' : '+');
      $submenu.stop(true, true).slideToggle(300);
    });

    function closeOtherMenus($currentParent) {
      const $others = $('.has-submenu').not($currentParent);
      $others.removeClass('submenu-open');
      $others.children('.nav-sub-menu-block').stop(true, true).slideUp(300);
      $others.find('.sub-menu-toggle-btn').text('+');
    }

  }

  $(document).ready(function () {
    initDefaultSubmenu();
  });

  $(window).on('load resize', function () {
    handleSubmenuEvents();
  });
  // Menu JS End

  // FAQ Accordion JS
  $('.faq-accordion-title').on('click', function () {
    const $faqAccordion = $(this).closest('.faq-accordion');

    if ($faqAccordion.hasClass('active')) {
      $faqAccordion.removeClass('active').find('.faq-accordion-content').stop(true, true).slideUp();
    } else {
      $('.faq-accordion.active').removeClass('active').find('.faq-accordion-content').stop(true, true).slideUp();
      $faqAccordion.addClass('active').find('.faq-accordion-content').stop(true, true).slideDown();
    }
  });
  $('.faq-accordion-title').first().trigger('click');
  // FAQ Accordion JS End

  // Footer Form Klaviyo Integration Start
  $(document).ready(function () {
    $('.footer-form').on('submit', function (e) {
      e.preventDefault();

      var $form = $(this);

      $.ajax({
        url: 'https://manage.kmail-lists.com/ajax/subscriptions/subscribe',
        type: 'POST',
        data: $form.serialize(),
        dataType: 'json',

        success: function (response) {
          if (response.success) {
            $form.hide();
            $form.siblings('.w-form-done').show();
            $form.siblings('.w-form-fail').hide();
          } else {
            $form.siblings('.w-form-fail').show();
          }
        },

        error: function () {
          $('.form-error').show();
          $('.form-success').hide();
        },
      });
    });
  });
  // Footer Form Klaviyo Integration End

  // Stay In Touch Form Klaviyo Integration Start
  $(document).ready(function () {
    $('.stay-in-touch-form').on('submit', function (e) {
      e.preventDefault();

      var $form = $(this);

      $.ajax({
        url: 'https://manage.kmail-lists.com/ajax/subscriptions/subscribe',
        type: 'POST',
        data: $form.serialize(),
        dataType: 'json',

        success: function (response) {
          if (response.success) {
            $form.hide();
            $form.siblings('.w-form-done').show();
            $form.siblings('.w-form-fail').hide();
          } else {
            $form.siblings('.w-form-fail').show();
          }
        },

        error: function () {
          $('.form-error').show();
          $('.form-success').hide();
        },
      });
    });
  });
  // Stay In Touch Form Klaviyo Integration End

  // hide and show image in header banner image JS start
  document.addEventListener('DOMContentLoaded', function () {
    const container = document.querySelector('.case-d-hero-image-or-video');

    if (container) {
      const mobileImg = container.querySelector('.case-m-hero-image');

      if (!mobileImg) {
        const desktopImg = container.querySelector('.case-d-hero-image');
        if (desktopImg) {
          desktopImg.style.display = 'block';
        }
      }
    }
  });
  // hide and show image in header banner image JS end
</script><script src="https://cookie-consent-cdn-prod.pages.dev/cookie-consent/3.0.33/cookie-consent.js" type="text/javascript" integrity="sha384-hID7SQtXLqNKM1f6agvO2qhK2radQn5wf+Su4pAEM5ElgJ/FmSWXrmcaYP4/D3E0" crossorigin="anonymous"></script></body></html>

